// ============================================================
// CLASSES: the curriculum (data only).
//
//   Course -> Unit -> Topic -> Skill
//
// Activities live in activities.mjs and point at skill ids, so one
// activity can serve several topics or courses, and topics can be added,
// moved or reordered here without touching any page code.
// Pages are generated from this file: after editing, run
//   node scripts/build-classes.mjs
//
// IDS ARE PERMANENT. Student progress is stored against skill ids, so:
//   - never change an id once published (change the title instead);
//   - moving a topic to another unit keeps its id;
//   - ids don't contain unit numbers, so reordering units is safe.
// Topic id = <course id>.<topic slug>; skill id = <topic id>.<skill slug>.
// The topic slug is also its address: /classes/<course slug>/<topic slug>/
//
// Topic fields:
//   slug, title, desc (one or two sentences),
//   mtb  (the mountain biking connection; left out where there isn't an
//         honest one rather than invented),
//   skills: ['slug: What the student will be able to do', ...]
//   prereq?: [topic ids] that help to know first
// ============================================================

const T = (slug, title, desc, mtb, skills, extra) => ({ slug, title, desc, mtb: mtb || null, skills, ...(extra || {}) });

